class Solution {
public:
    bool isScramble(string s1, string s2) {
        int n = s1.length();

        // Quick prune: character multisets must match
        string t1 = s1, t2 = s2;
        sort(t1.begin(), t1.end());
        sort(t2.begin(), t2.end());
        if (t1 != t2) return false;

        // dp[i][j][len]: s1[i..i+len-1] is a scramble of s2[j..j+len-1]
        vector<vector<vector<bool>>> dp(n, vector<vector<bool>>(n, vector<bool>(n + 1, false)));

        // Base case: length 1
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                dp[i][j][1] = (s1[i] == s2[j]);

        // Fill for increasing lengths
        for (int len = 2; len <= n; len++) {
            for (int i = 0; i + len <= n; i++) {
                for (int j = 0; j + len <= n; j++) {
                    for (int k = 1; k < len; k++) {
                        // No swap: s1[i..i+k-1] <-> s2[j..j+k-1], s1[i+k..] <-> s2[j+k..]
                        if (dp[i][j][k] && dp[i + k][j + k][len - k]) {
                            dp[i][j][len] = true;
                            break;
                        }
                        // Swap: s1[i..i+k-1] <-> s2[j+len-k..j+len-1], s1[i+k..] <-> s2[j..j+len-k-1]
                        if (dp[i][j + len - k][k] && dp[i + k][j][len - k]) {
                            dp[i][j][len] = true;
                            break;
                        }
                    }
                }
            }
        }

        return dp[0][0][n];
    }
};
